-- dsl-03-specification.commit.sql
--
-- ============================== COMMIT - THIS INSTALLS ==============================
-- Byte-identical to the preflight twin except this banner and the terminal statement:
-- COMMIT TRANSACTION here, ROLLBACK TRANSACTION there. Run the preflight first.
--
-- WHAT THIS CHANGES: capability-dsl-specification.v1 (AUTHORITY sidefx:authorities) lists the grammar the compiler
-- accepts after dsl-02: 29 constructs (the 19 it had, with scenario, operation, platform bind, config and provider
-- binding brought up to date, plus inquiry, contract, variants, outcome-variants, cli input, cli reading, route,
-- broadcast, join and recur) and 25 document-semantics rows, including the semanticProgress each routing line emits.
-- It goes through the installed writer model.replace_capability_dsl_specification (the writer behind the
-- capability-dsl-specification-change kind), which replaces only constructs and documentSemantics here. The conformance
-- vectors, naming, validation codes and resolver placement are unchanged.
--
-- WHERE: the estate database. Run the whole file in one session; the transaction spans the batches.
--
-- BASES: the writer sha256:bc1aeb30cde0893965e1d9c7ecb4ebe640cf35e9943985ec568dfe06992686e4 (run ea14c8a0); the specification as read on 2026-11-02 (run 67588f36,
-- definition sha256:bd9a44ae08d1576dd876895f18b3a43c806caff767ecb0c8ef1ec3731cd6a88e): its 19 constructs and 15 semantics rows must equal, row for row, the ones
-- embedded below; and analysis.compile_capability_dsl must be the dsl-02 revision (sha256:0597a496f621d84de4e4cdcdf10dd1dd1688dda4d7c2d86e1ec0e67e32efa9fd). Otherwise the file stops
-- before any change.
--
-- VERIFY (in the transaction): the selected specification holds exactly the 29 constructs and 25 semantics rows, and its
-- 8 vectors are unchanged. Otherwise nothing is kept.
--
-- RESULT SETS: base; capability_dsl_specification (the writer's own row); readback.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @w varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),OBJECT_DEFINITION(OBJECT_ID(N'model.replace_capability_dsl_specification')) COLLATE Latin1_General_100_BIN2_UTF8)),2));
DECLARE @cd nvarchar(max)=REPLACE(OBJECT_DEFINITION(OBJECT_ID(N'analysis.compile_capability_dsl')),NCHAR(13)+NCHAR(10),NCHAR(10));
SET @cd=SUBSTRING(@cd,CHARINDEX(N'PROCEDURE analysis.compile_capability_dsl',@cd),DATALENGTH(@cd)/2);
WHILE DATALENGTH(@cd)>0 AND RIGHT(@cd,1) IN (NCHAR(10),NCHAR(13),NCHAR(32),NCHAR(9)) SET @cd=LEFT(@cd,DATALENGTH(@cd)/2-1);
DECLARE @cd_digest varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),@cd COLLATE Latin1_General_100_BIN2_UTF8)),2));
DECLARE @spec nvarchar(max),@spec_digest varchar(80);
SELECT TOP (1) @spec=CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8),@spec_digest='sha256:'+LOWER(CONVERT(varchar(64),co.content_digest,2))
FROM model.estate_definition ed
JOIN model.semantic_object_definition d ON d.semantic_object_definition_pk=ed.semantic_object_definition_pk
JOIN model.semantic_object so ON so.semantic_object_pk=d.semantic_object_pk
JOIN model.identity_namespace n ON n.namespace_pk=so.namespace_pk
JOIN source.content_object co ON co.content_object_pk=d.canonical_content_pk
WHERE ed.estate_model_pk=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1) AND so.object_kind=N'AUTHORITY'
 AND n.namespace_id=N'sidefx:authorities' COLLATE Latin1_General_100_BIN2 AND so.declared_id=N'capability-dsl-specification.v1' COLLATE Latin1_General_100_BIN2
ORDER BY d.semantic_object_definition_pk DESC;
DECLARE @base_constructs nvarchar(max)=N'[{"constructId":"capability","form":"capability <capability-id>","attachesTo":"document","rule":"Exactly one; it opens the document."},{"constructId":"intent","form":"intent: <free text>","attachesTo":"document","rule":"Free text to end of line, trimmed."},{"constructId":"outcome","form":"outcome: <free text>","attachesTo":"document","rule":"Free text to end of line, trimmed."},{"constructId":"inputContract","form":"input contract <contract-id> <inline-json>","attachesTo":"document","rule":"Single-line JSON object: the schema exactly as it must appear in the document; validated by ISJSON plus the executor preflight, not a second schema engine."},{"constructId":"outputContract","form":"output contract <contract-id> <inline-json>","attachesTo":"document","rule":"Single-line JSON object: the schema exactly as it must appear in the document."},{"constructId":"cliDisplay","form":"cli display <select> as <format>","attachesTo":"document","rule":"Recognized format: json."},{"constructId":"scenario","form":"scenario <scenario-id> [root] [terminal]","attachesTo":"document","rule":"At least one; the root and terminal flags are optional and may appear in either order after the id."},{"constructId":"given","form":"given: <free text>","attachesTo":"most recent scenario","rule":"Free text to end of line, trimmed."},{"constructId":"when","form":"when: <free text>","attachesTo":"most recent scenario","rule":"Free text to end of line, trimmed."},{"constructId":"then","form":"then: <free text>","attachesTo":"most recent scenario","rule":"Free text to end of line, trimmed."},{"constructId":"operation","form":"operation <operation-id> kind <kind> port <port-id>","attachesTo":"most recent scenario","rule":"Recognized kind: invoke-port; the port must have a matching bind in the same scenario."},{"constructId":"bind","form":"bind <port-id>","attachesTo":"most recent scenario","rule":"The declared-statement binding: the four keys platform, provider, statement and result attach to it and are all mandatory."},{"constructId":"platformBind","form":"platform bind <port-id>","attachesTo":"most recent scenario","rule":"The platform-port binding: the platform key is mandatory; exactly one of provider or config follows. provider names the platform provider (configuration {providerId}); config carries the port configuration verbatim as a single-line JSON object. statement and result are not admitted."},{"constructId":"config","form":"config: <inline-json>","attachesTo":"most recent bind","rule":"The port configuration verbatim: a single-line JSON object emitted as the binding configuration; \"@provider-binding:<id>\" strings resolve to the declared sidecar digest. Admitted only on a platform bind, where it replaces the provider key."},{"constructId":"platform","form":"platform: <platform-capability-id>","attachesTo":"most recent bind","rule":"Must name a platform capability declared in the estate."},{"constructId":"provider","form":"provider: <provider-id>","attachesTo":"most recent bind","rule":"Must name a provider declared in the estate."},{"constructId":"statement","form":"statement: <statement text>","attachesTo":"most recent bind","rule":"Free text to end of line, trimmed."},{"constructId":"result","form":"result: <result-column>","attachesTo":"most recent bind","rule":"Free text to end of line, trimmed."},{"constructId":"providerBinding","form":"provider binding <id> <inline-json>","attachesTo":"document","rule":"Declares a sidecar provider-input-binding artifact: compiled into the result providerBindings[] with a deterministic content digest; configurations reference it as \"@provider-binding:<id>\". The author path mints the artifact as raw content-addressed authority in the same governed transaction."}]';
DECLARE @base_semantics nvarchar(max)=N'[{"constructId":"capability","documentMember":"$.capabilityId","mapping":"capabilityId = the id"},{"constructId":"intent","documentMember":"$.meaning.intent","mapping":"meaning.intent = the free text"},{"constructId":"outcome","documentMember":"$.meaning.outcome","mapping":"meaning.outcome = the free text"},{"constructId":"inputContract","documentMember":"$.cli.input and $.contracts[]","mapping":"cli.input = {type: json, contract: id}; contracts[] += {id, schema: the inline-json}"},{"constructId":"outputContract","documentMember":"$.contracts[]","mapping":"contracts[] += {id, schema: the inline-json}"},{"constructId":"cliDisplay","documentMember":"$.cli.display","mapping":"cli.display = {select, as}"},{"constructId":"scenario","documentMember":"$.scenarios[]","mapping":"scenarioId = id; name = id with - mapped to spaces and first letter capitalized; inputId = <id>-request; inputContract = the input contract id; eventId = <id>-requested; eventAuthority = <capabilityId>.v1; outcomeId = <id>; outcomeContract = the output contract id; root and terminal flags as declared"},{"constructId":"given","documentMember":"scenarios[last].given","mapping":"given = the free text"},{"constructId":"when","documentMember":"scenarios[last].when","mapping":"when = the free text"},{"constructId":"then","documentMember":"scenarios[last].then","mapping":"then = the free text"},{"constructId":"operation","documentMember":"scenarios[last].operations[]","mapping":"operations[] += {operationId, kind, portId}"},{"constructId":"bind","documentMember":"scenarios[last].portBindings[]","mapping":"portBindings[] += {portId, platformCapabilityId: platform, configuration: {statement, resultColumn: result, providerId: provider}}"},{"constructId":"platformBind","documentMember":"scenarios[last].portBindings[]","mapping":"portBindings[] += {portId, platformCapabilityId: platform, configuration: provider ? {providerId: provider} : the config inline-json verbatim}"},{"constructId":"config","documentMember":"scenarios[last].portBindings[].configuration","mapping":"configuration = the inline-json verbatim"},{"constructId":"providerBinding","documentMember":"compile-result providerBindings[] (sidecar)","mapping":"providerBindings[] += {providerBindingId, digest, content}; \"@provider-binding:<id>\" inside any configuration resolves to sha256:<digest>"}]';
DECLARE @cur_constructs nvarchar(max)=JSON_QUERY(@spec,N'$.semantics.constructs'),@cur_semantics nvarchar(max)=JSON_QUERY(@spec,N'$.semantics.documentSemantics');
DECLARE @c_count int=(SELECT COUNT(*) FROM OPENJSON(@cur_constructs)),@s_count int=(SELECT COUNT(*) FROM OPENJSON(@cur_semantics)),
 @c_diff int=(SELECT COUNT(*) FROM OPENJSON(@base_constructs) WITH (id nvarchar(64) N'$.constructId',form nvarchar(200) N'$.form',att nvarchar(64) N'$.attachesTo',rl nvarchar(400) N'$.rule') g WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@cur_constructs) WITH (id nvarchar(64) N'$.constructId',form nvarchar(200) N'$.form',att nvarchar(64) N'$.attachesTo',rl nvarchar(400) N'$.rule') n WHERE n.id=g.id COLLATE Latin1_General_100_BIN2 AND n.form=g.form COLLATE Latin1_General_100_BIN2 AND ISNULL(n.att,N'')=ISNULL(g.att,N'') COLLATE Latin1_General_100_BIN2 AND ISNULL(n.rl,N'')=ISNULL(g.rl,N'') COLLATE Latin1_General_100_BIN2)),
 @s_diff int=(SELECT COUNT(*) FROM OPENJSON(@base_semantics) WITH (id nvarchar(64) N'$.constructId',mem nvarchar(200) N'$.documentMember',map nvarchar(400) N'$.mapping') g WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@cur_semantics) WITH (id nvarchar(64) N'$.constructId',mem nvarchar(200) N'$.documentMember',map nvarchar(400) N'$.mapping') n WHERE n.id=g.id COLLATE Latin1_General_100_BIN2 AND n.mem=g.mem COLLATE Latin1_General_100_BIN2 AND ISNULL(n.map,N'')=ISNULL(g.map,N'') COLLATE Latin1_General_100_BIN2));
DROP TABLE IF EXISTS #dsl03_vectors;
SELECT JSON_QUERY(@spec,N'$.semantics.conformanceVectors') AS vectors INTO #dsl03_vectors;
SELECT N'base' AS result_set,@w AS writer_installed,'sha256:bc1aeb30cde0893965e1d9c7ecb4ebe640cf35e9943985ec568dfe06992686e4' AS writer_expected,@cd_digest AS compiler_body,'sha256:0597a496f621d84de4e4cdcdf10dd1dd1688dda4d7c2d86e1ec0e67e32efa9fd' AS compiler_expected,
 @spec_digest AS specification_content,@c_count AS constructs,@s_count AS semantics,@c_diff AS constructs_differing,@s_diff AS semantics_differing,
 (SELECT COUNT(*) FROM OPENJSON(JSON_QUERY(@spec,N'$.semantics.conformanceVectors'))) AS vectors;
IF @w IS NULL OR @w<>'sha256:bc1aeb30cde0893965e1d9c7ecb4ebe640cf35e9943985ec568dfe06992686e4' OR @cd_digest<>'sha256:0597a496f621d84de4e4cdcdf10dd1dd1688dda4d7c2d86e1ec0e67e32efa9fd' OR @spec IS NULL OR @c_count<>19 OR @s_count<>15 OR @c_diff<>0 OR @s_diff<>0
BEGIN
 RAISERROR(N'DSL03_BASE_MOVED: the writer, the compiler or the specification is not the reviewed base (run dsl-02 first); nothing is changed.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
SET NOCOUNT ON;
DECLARE @doc nvarchar(max)=N'{"grammar":{"constructs":[{"constructId":"capability","form":"capability <capability-id>","attachesTo":"document","rule":"Exactly one; it opens the document."},{"constructId":"intent","form":"intent: <free text>","attachesTo":"document","rule":"Free text to end of line, trimmed."},{"constructId":"outcome","form":"outcome: <free text>","attachesTo":"document","rule":"Free text to end of line, trimmed."},{"constructId":"inquiry","form":"inquiry: <free text>","attachesTo":"document","rule":"An example request the capability answers; at most three, kept in order."},{"constructId":"inputContract","form":"input contract <contract-id> <inline-json>","attachesTo":"document","rule":"Single-line JSON object: the schema exactly as it must appear in the document; validated by ISJSON plus the executor preflight, not a second schema engine."},{"constructId":"outputContract","form":"output contract <contract-id> <inline-json>","attachesTo":"document","rule":"Single-line JSON object: the schema exactly as it must appear in the document."},{"constructId":"contract","form":"contract <contract-id> <inline-json>","attachesTo":"document","rule":"A further contract, for a scenario that names it with input= or output=. Single-line JSON object; its id differs from the input and output contract ids."},{"constructId":"cliDisplay","form":"cli display <select> as <format>","attachesTo":"document","rule":"Recognized format: json."},{"constructId":"cliInput","form":"cli input json | cli input text <payload-path>","attachesTo":"document","rule":"How the CLI reads the request: json (the default), or text placed at the payload path."},{"constructId":"cliReading","form":"cli reading <reading> <altitude>[,<altitude>...]","attachesTo":"document","rule":"A named CLI reading and the altitudes it shows."},{"constructId":"scenario","form":"scenario <scenario-id> [root] [terminal] [input=<contract-id>] [output=<contract-id>]","attachesTo":"document","rule":"At least one; flags in any order after the id. At most one root: the CLI interface addresses it, and each independently invocable entry is its own capability. input= and output= name a contract of this document; they default to the input and output contracts."},{"constructId":"given","form":"given: <free text>","attachesTo":"most recent scenario","rule":"Free text to end of line, trimmed."},{"constructId":"when","form":"when: <free text>","attachesTo":"most recent scenario","rule":"Free text to end of line, trimmed."},{"constructId":"then","form":"then: <free text>","attachesTo":"most recent scenario","rule":"Free text to end of line, trimmed."},{"constructId":"variants","form":"variants: <variant>:success|failure[,<variant>:success|failure...]","attachesTo":"most recent scenario","rule":"The scenario''s outcome variants, each classified success or failure; a route or recur from the scenario names one of them. :terminal is refused here: a scenario that ends the capability takes the terminal flag."},{"constructId":"operation","form":"operation <operation-id> kind invoke-port port <port-id> | kind invoke-scenario scenario <scenario-id> | kind for-each port <port-id> over <path> [max <n>]","attachesTo":"most recent scenario","rule":"invoke-port and for-each need a bind of the port in the same scenario; for-each folds the bound port over the collection at the path, at most max times (2147483647 without max). invoke-scenario names a scenario of this document; routes and invoke-scenario operations form no cycle."},{"constructId":"outcomeVariants","form":"outcome-variants: <variant>:success|failure[:terminal][,...]","attachesTo":"most recent operation","rule":"The operation''s outcome variants, each classified success or failure; :terminal marks a variant that ends the capability."},{"constructId":"bind","form":"bind <port-id>","attachesTo":"most recent scenario","rule":"The declared-statement binding: the four keys platform, provider, statement and result attach to it and are all mandatory."},{"constructId":"platformBind","form":"platform bind <port-id>","attachesTo":"most recent scenario","rule":"The platform-port binding: platform is mandatory, with provider, config or both. provider alone gives configuration {providerId}; config carries the port configuration verbatim, and a provider beside it is added as its providerId. statement and result are not admitted."},{"constructId":"config","form":"config: <inline-json>","attachesTo":"most recent bind","rule":"The port configuration verbatim: a single-line JSON object. \"@provider-binding:<id>\" strings resolve to the digest of the provider binding with that id; a name no provider binding declares refuses. Admitted only on a platform bind."},{"constructId":"platform","form":"platform: <platform-capability-id>","attachesTo":"most recent bind","rule":"Must name a platform capability declared in the estate."},{"constructId":"provider","form":"provider: <provider-id>","attachesTo":"most recent bind","rule":"Must name a provider declared in the estate."},{"constructId":"statement","form":"statement: <statement text>","attachesTo":"most recent bind","rule":"Free text to end of line, trimmed."},{"constructId":"result","form":"result: <result-column>","attachesTo":"most recent bind","rule":"Free text to end of line, trimmed."},{"constructId":"providerBinding","form":"provider binding <id> <inline-json>","attachesTo":"document","rule":"Declares a sidecar provider-input-binding artifact: its JSON without the whitespace outside strings, addressed by sha256 over its UTF-8 bytes, compiled into the result providerBindings[]; configurations reference it as \"@provider-binding:<id>\". The author path mints the artifact as raw content-addressed authority in the same governed transaction."},{"constructId":"route","form":"route <from-scenario> <variant> to <to-scenario>","attachesTo":"document","rule":"One selection transition. Both scenarios and the variant on the from scenario are declared, and adjacent contracts agree. Routes form no cycle: a loop is a recur line. semanticProgress is terminating into a terminal scenario, otherwise narrowing."},{"constructId":"broadcast","form":"broadcast <root-scenario> to <leg>,<leg>[,<leg>...]","attachesTo":"document","rule":"At most one per capability, with a join over the same legs. Every leg runs concurrently (semanticProgress expanding); the capability''s input and output contracts share one id."},{"constructId":"join","form":"join <join-scenario> from <leg>,<leg>[,<leg>...]","attachesTo":"document","rule":"At most one per capability; it converges the legs of the broadcast (the same set), all required. A join without a broadcast refuses. Settle and failure transitions are converging."},{"constructId":"recur","form":"recur <scenario> while <continue-variant> until <stop-variant> [max <n>]","attachesTo":"document","rule":"A bounded recurrence of one scenario on itself: both variants are declared on it, and its outcome contract equals its input contract. Without max the bound is 2147483647. semanticProgress is recurring."}],"documentSemantics":[{"constructId":"capability","documentMember":"$.capabilityId","mapping":"capabilityId = the id"},{"constructId":"intent","documentMember":"$.meaning.intent","mapping":"meaning.intent = the free text"},{"constructId":"outcome","documentMember":"$.meaning.outcome","mapping":"meaning.outcome = the free text"},{"constructId":"inquiry","documentMember":"$.inquiries[]","mapping":"inquiries[] += the free text, in order"},{"constructId":"inputContract","documentMember":"$.cli.input and $.contracts[]","mapping":"cli.input = {type, contract: id}; contracts[] += {id, schema: the inline-json without the whitespace outside strings}"},{"constructId":"outputContract","documentMember":"$.contracts[]","mapping":"contracts[] += {id, schema}, once when its id is the input contract id"},{"constructId":"contract","documentMember":"$.contracts[]","mapping":"contracts[] += {id, schema: the inline-json}, after the input and output contracts"},{"constructId":"cliDisplay","documentMember":"$.cli.display","mapping":"cli.display = {select, as}"},{"constructId":"cliInput","documentMember":"$.cli.input","mapping":"cli.input.type = json or text; text adds cli.input.path = the payload path"},{"constructId":"cliReading","documentMember":"$.cli.readings[]","mapping":"cli.readings[] += {reading, altitudes[]}"},{"constructId":"scenario","documentMember":"$.scenarios[]","mapping":"scenarioId = id; name = id with - mapped to spaces, first letter capitalized; inputId = <id>-request; inputContract = input= or the input contract; eventId = <id>-requested; eventAuthority = <capabilityId>.v1 for the root, otherwise <id>.v1; outcomeId = <id>-outcome; outcomeContract = output= or the output contract; root and terminal"},{"constructId":"given","documentMember":"scenarios[last].given","mapping":"given = the free text"},{"constructId":"when","documentMember":"scenarios[last].when","mapping":"when = the free text"},{"constructId":"then","documentMember":"scenarios[last].then","mapping":"then = the free text"},{"constructId":"variants","documentMember":"scenarios[last].variants[]","mapping":"variants[] += {variantId, classification}"},{"constructId":"operation","documentMember":"scenarios[last].operations[]","mapping":"operations[] += {operationId, kind: invoke-port, portId} or {operationId, kind: invoke-scenario, scenarioId}; for-each: the bound port''s configuration plus operationId, kind, portId, bodyCapabilityId = the platform, collectionValuePath, maximumIterations"},{"constructId":"outcomeVariants","documentMember":"scenarios[last].operations[last].outcomeVariants[]","mapping":"outcomeVariants[] += {variantId, classification}, with terminal: true for :terminal"},{"constructId":"bind","documentMember":"scenarios[last].portBindings[]","mapping":"portBindings[] += {portId, platformCapabilityId: platform, configuration: {statement, resultColumn: result, providerId: provider}}"},{"constructId":"platformBind","documentMember":"scenarios[last].portBindings[]","mapping":"portBindings[] += {portId, platformCapabilityId: platform, configuration: the config verbatim with providerId = provider when both are given, or {providerId: provider}}"},{"constructId":"config","documentMember":"scenarios[last].portBindings[].configuration","mapping":"configuration = the inline-json verbatim, each \"@provider-binding:<id>\" replaced by that binding''s sha256 digest"},{"constructId":"providerBinding","documentMember":"compile-result providerBindings[] (sidecar)","mapping":"providerBindings[] += {providerBindingId, digest, content}; \"@provider-binding:<id>\" inside any configuration resolves to the digest"},{"constructId":"route","documentMember":"$.routing[]","mapping":"routing[] += {transitionId: route-<from>-<variant>, fromScenario, variant, toScenario, topologyKind: selection, semanticProgress: terminating into a terminal scenario, otherwise narrowing}"},{"constructId":"broadcast","documentMember":"$.routing[] and $.executionGraph","mapping":"routing[] += enter-<leg> {broadcast, groupId <capabilityId>.fan, semanticProgress expanding}; executionGraph = sda-semantic-execution-graph.v2 with dispatch authority <capabilityId>.dispatch and edge groups <capabilityId>.fan (all) and <capabilityId>.converge (all-required)"},{"constructId":"join","documentMember":"$.routing[]","mapping":"routing[] += settle-<leg> {join, groupId <capabilityId>.converge, joinSlotId <leg>, semanticProgress converging} and fail-<leg> {failure, the same group and slot, semanticProgress converging}"},{"constructId":"recur","documentMember":"$.routing[] and $.executionGraph","mapping":"routing[] += recur-<scenario> {recurrence, variant: the continue variant, groupId <capabilityId>.recur-<scenario>, recurrenceAuthorityId, semanticProgress recurring}; executionGraph.recurrenceAuthorities[] += {continuationVariant, stopVariant, maximumIterations, authorityDigest}"}]}}';
EXEC model.replace_capability_dsl_specification @document=@doc;
DECLARE @spec nvarchar(max),@spec_digest varchar(80);
SELECT TOP (1) @spec=CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8),@spec_digest='sha256:'+LOWER(CONVERT(varchar(64),co.content_digest,2))
FROM model.estate_definition ed
JOIN model.semantic_object_definition d ON d.semantic_object_definition_pk=ed.semantic_object_definition_pk
JOIN model.semantic_object so ON so.semantic_object_pk=d.semantic_object_pk
JOIN model.identity_namespace n ON n.namespace_pk=so.namespace_pk
JOIN source.content_object co ON co.content_object_pk=d.canonical_content_pk
WHERE ed.estate_model_pk=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1) AND so.object_kind=N'AUTHORITY'
 AND n.namespace_id=N'sidefx:authorities' COLLATE Latin1_General_100_BIN2 AND so.declared_id=N'capability-dsl-specification.v1' COLLATE Latin1_General_100_BIN2
ORDER BY d.semantic_object_definition_pk DESC;
DECLARE @want_constructs nvarchar(max)=JSON_QUERY(@doc,N'$.grammar.constructs'),@want_semantics nvarchar(max)=JSON_QUERY(@doc,N'$.grammar.documentSemantics');
DECLARE @cur_constructs nvarchar(max)=JSON_QUERY(@spec,N'$.semantics.constructs'),@cur_semantics nvarchar(max)=JSON_QUERY(@spec,N'$.semantics.documentSemantics');
DECLARE @c_count int=(SELECT COUNT(*) FROM OPENJSON(@cur_constructs)),@s_count int=(SELECT COUNT(*) FROM OPENJSON(@cur_semantics)),
 @c_diff int=(SELECT COUNT(*) FROM OPENJSON(@want_constructs) WITH (id nvarchar(64) N'$.constructId',form nvarchar(200) N'$.form',att nvarchar(64) N'$.attachesTo',rl nvarchar(400) N'$.rule') g WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@cur_constructs) WITH (id nvarchar(64) N'$.constructId',form nvarchar(200) N'$.form',att nvarchar(64) N'$.attachesTo',rl nvarchar(400) N'$.rule') n WHERE n.id=g.id COLLATE Latin1_General_100_BIN2 AND n.form=g.form COLLATE Latin1_General_100_BIN2 AND ISNULL(n.att,N'')=ISNULL(g.att,N'') COLLATE Latin1_General_100_BIN2 AND ISNULL(n.rl,N'')=ISNULL(g.rl,N'') COLLATE Latin1_General_100_BIN2)),
 @s_diff int=(SELECT COUNT(*) FROM OPENJSON(@want_semantics) WITH (id nvarchar(64) N'$.constructId',mem nvarchar(200) N'$.documentMember',map nvarchar(400) N'$.mapping') g WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@cur_semantics) WITH (id nvarchar(64) N'$.constructId',mem nvarchar(200) N'$.documentMember',map nvarchar(400) N'$.mapping') n WHERE n.id=g.id COLLATE Latin1_General_100_BIN2 AND n.mem=g.mem COLLATE Latin1_General_100_BIN2 AND ISNULL(n.map,N'')=ISNULL(g.map,N'') COLLATE Latin1_General_100_BIN2)),
 @v_same bit=CASE WHEN JSON_QUERY(@spec,N'$.semantics.conformanceVectors')=(SELECT vectors FROM #dsl03_vectors) COLLATE Latin1_General_100_BIN2 THEN 1 ELSE 0 END;
SELECT N'readback' AS result_set,@spec_digest AS specification_content,@c_count AS constructs,@s_count AS semantics,@c_diff AS constructs_differing,@s_diff AS semantics_differing,
 (SELECT COUNT(*) FROM OPENJSON(JSON_QUERY(@spec,N'$.semantics.conformanceVectors'))) AS vectors,@v_same AS vectors_unchanged;
IF @c_count<>29 OR @s_count<>25 OR @c_diff<>0 OR @s_diff<>0 OR @v_same<>1
BEGIN
 RAISERROR(N'DSL03_VERIFY_FAILED: the specification does not hold exactly the reviewed grammar with its vectors unchanged; nothing is kept.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
DROP TABLE IF EXISTS #dsl03_vectors;
COMMIT TRANSACTION;
GO
SET NOEXEC OFF;
